prompt --application/shared_components/security/authentications/oracle_apex_accounts
begin
wwv_flow_imp_shared.create_authentication(
 p_id=>wwv_flow_imp.id(14987800234974678)
,p_name=>'Oracle APEX Accounts'
,p_static_id=>'oracle-apex-accounts'
,p_scheme_type=>'NATIVE_CUSTOM'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'authentication_function', 'autenticar_usuario_apex',
  'enable_legacy_attributes', 'N')).to_clob
,p_plsql_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'   SELECT COALESCE(',
'             (SELECT CASE ',
'                       WHEN u.nombrerol IN (''CONTRATISTA'', ''FISCALIZADOR'') THEN 9',
'                       ELSE 1',
'                     END',
'                FROM usuarios_roles_view u',
'               WHERE u.nombreusuario = :APP_USER',
'                 AND u.nombrerol IN (''CONTRATISTA'', ''FISCALIZADOR'')',
'               FETCH FIRST 1 ROWS ONLY),',
'             1',
'          )',
'     INTO :APP_HOME_PAGE',
'     FROM DUAL;',
'EXCEPTION',
'   WHEN OTHERS THEN',
'      :APP_HOME_PAGE := 1;',
'END;'))
,p_invalid_session_type=>'LOGIN'
,p_cookie_name=>'NUEVA_SESION_APP10000'
,p_use_secure_cookie_yn=>'N'
,p_ras_mode=>0
,p_version_scn=>'SH256:TC74SsBQ6twgGp0gZ9KK9GT5fBrGxPOlhi1qbpeqjCI'
,p_created_on=>wwv_flow_imp.dz('20260515033301Z')
,p_updated_on=>wwv_flow_imp.dz('20260823165201Z')
,p_created_by=>'GPROY_ELEL'
,p_updated_by=>'GPROY_ELEL'
);
end;
