 p_id=>wwv_flow_imp.id(20090783079167439)
,p_computation_sequence=>20
,p_computation_item=>'P6_MESNAJE_DE_EXITO'
,p_static_id=>'p6-mesnaje-de-exito'
,p_computation_type=>'QUERY'
,p_computation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT COALESCE(MAX(nombre_estados), ''Solicitud procesada correctamente'')',
'  FROM estados_configurados',
' WHERE estado_id = :P6_ESTADO_SOLICITUD_ID',
'   AND tipo_estado = ''SOLICITUDES DE PROYECTOS'''))
,p_computation_error_message=>wwv_flow_string.join(wwv_flow_t_varchar2(
'Estado no encontrado.',
'#SQLERRM#'))
,p_compute_when=>'P6_ESTADO_SOLICITUD_ID'
,p_compute_when_type=>'ITEM_IS_NOT_NULL'
,p_created_on=>wwv_flow_imp.dz('20260718180508Z')
,p_updated_on=>wwv_flow_imp.dz('20260718180927Z')
