 p_id=>wwv_flow_imp.id(35933367979348917)
,p_name=>'Bandeja de Proyectos'
,p_static_id=>'bandeja-de-proyectos'
,p_template=>4073835273271169698
,p_display_sequence=>40
,p_region_template_options=>'#DEFAULT#:t-Region--noPadding:t-Region--hideHeader js-addHiddenHeadingRoleDesc:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#:t-Report--stretch:t-Report--staticRowColors:t-Report--rowHighlight:t-Report--inline:t-Report--hideNoPagination'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select PROYECTO_ID,',
'       NOMBRE_PROYECTO,',
'       MONTO,',
'       FECHA_CREACION,',
'       FECHA_INICIO_EJECUCION,',
'       FECHA_FIN_EJECUCION,',
'       ESTADO_PROYECTO_ID,',
'       OFERTA_ID,',
'       ANTICIPO_VALOR,',
'       FECHA_DEPOSITO_ANTICIPO,',
'       NRO_CTA_ORIGEN,',
'       SALDO,',
'       VALOR_RESTANTE,',
'       ENTIDAD_BANCARIA_ANTICIPO_ID,',
'       ENTIDAD_BANCARIA_VALREST_ID,',
'       INFORMACION_ADICIONAL,',
'       NOMBRE_ENTIDAD_FINANCIERA,',
'       NOMBRE_SECTOR,',
'       SECTOR_ID,',
'       TIPO_PROYECTO_ID,',
'       NOMBRE_TIPO_PROYECTO,',
'       EMPRESA_ID,',
'       NOMBRE_EMPRESA,',
'       ESTADO_ID,',
'       NOMBRE_ESTADOS,',
'       CASE ',
'           WHEN ESTADO_ID = 1 THEN ''Y'' --''Proyecto APROBADO''',
'           ELSE ''N''',
'       END as MOSTRAR_BOTON_CONTRATO',
'  from PROYECTO_VIEW',
'  where ESTADO_ID=1',
'    '))
,p_ajax_enabled=>'Y'
,p_fixed_header=>'PAGE'
,p_lazy_loading=>false
,p_query_row_template=>2540130677583398057
,p_query_num_rows=>50
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_no_data_found=>'no data found'
,p_query_num_rows_type=>'NEXT_PREVIOUS_LINKS'
,p_query_row_count_max=>500
,p_pagination_display_position=>'BOTTOM_RIGHT'
,p_prn_output=>'N'
,p_prn_format=>'PDF'
,p_sort_null=>'L'
,p_plug_query_strip_html=>'N'
,p_comment=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select ID,',
'       PROYECTO,',
'       MONTO,',
'       FECHA_INICIO,',
'       FECHA_FIN,',
'       PLAZO,',
'       SECTOR_ID,',
'       TIPO_PROYECTO_ID,',
'       OBSERVACIONES,',
'       TIPO,',
'       CASE tipo',
'           WHEN ''SOLICITUD'' THEN ',
'               APEX_PAGE.GET_URL(p_page => 8, p_items => ''P8_SOLICITUD_PROYECTO_ID'', p_values => id, p_clear_cache => ''8'')',
'           WHEN ''OFERTA''    THEN ',
'               APEX_PAGE.GET_URL(p_page => 15, p_items => ''P15_OFERTA_ID'',    p_values => id, p_clear_cache => ''15'')',
'           ELSE NULL ',
'       END as url_formulario,',
'       nombre_sector,',
'       nombre_tipo_proyecto,',
'       nombre_estados,',
'       CASE nombre_estados ',
unistr('       WHEN ''Aprobada para Postulaci\00F3n''           THEN ''#D4EDDA''  -- Verde claro'),
'        WHEN ''Rechazar Solicitud''                  THEN ''#F8D7DA''  -- Rojo claro',
unistr('        WHEN ''Registrado - Pendiente de Evaluaci\00F3n'' THEN ''#FFF3CD''  -- Amarillo claro'),
'        ELSE ''transparent''',
'       END AS CLASE_ESTADO',
'  from LISTADO_GESTION_PRECONTRACTUAL_VIEW/*DESCRIPCION_SOLICITUD,',
'       ESTADOSOLICITUD,',
'       CASE ESTADOSOLICITUD ',
unistr('       WHEN ''Aprobada para Postulaci\00F3n''           THEN ''#D4EDDA''  -- Verde claro'),
'        WHEN ''Rechazar Solicitud''                  THEN ''#F8D7DA''  -- Rojo claro',
unistr('        WHEN ''Registrado - Pendiente de Evaluaci\00F3n'' THEN ''#FFF3CD''  -- Amarillo claro'),
'        ELSE ''transparent''',
'       END AS CLASE_ESTADO,*/',
'       /*ESTADOSOLICITUD1,',
'       JUSTIFICACION_TECNICA,',
'       CIUDAD,',
'       PARROQUIA_ID,',
'       TIPO_PROYECTO_ID,',
'       NOMBRE_TIPO_PROYECTO,',
'       RESPONSABLE_ID,',
'       SECTOR_ID,',
'       SECTOR,',
'       NOMBRE_PARROQUIA,',
'       EMPRESA_ID,',
'       NOMBRE_EMPRESA*/',
'',
'',
'       '))
,p_created_on=>wwv_flow_imp.dz('20260626155512Z')
,p_updated_on=>wwv_flow_imp.dz('20260719035322Z')
