wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(17147839822299043)
,p_name=>'Solicitudes de Proyectos'
,p_static_id=>'solicitudes-de-proyectos'
,p_template=>4073835273271169698
,p_display_sequence=>10
,p_region_template_options=>'#DEFAULT#:t-Region--noPadding:t-Region--hideHeader js-addHiddenHeadingRoleDesc:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#:t-Report--stretch:t-Report--staticRowColors:t-Report--rowHighlight:t-Report--inline:t-Report--hideNoPagination'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select ID,',
'       PROYECTO,',
'       MONTO,',
'       FECHA_INICIO,',
'       FECHA_FIN,',
'       PLAZO,',
'       SECTOR_ID,',
'       TIPO_PROYECTO_ID,',
'       OBSERVACIONES,',
'       TIPO,',
'       DEPENDENCIA,',
'       -- Modificamos la URL: Si el estado es 3, el enlace se rompe devolviendo un ''#''',
'       CASE ',
unistr('           WHEN /*nombre_estados = ''Aprobada para Postulaci\00F3n''*/DEPENDENCIA IS NULL THEN ''#'''),
'           WHEN tipo = ''SOLICITUD'' THEN ',
'               APEX_PAGE.GET_URL(p_page => 8, p_items => ''P8_SOLICITUD_PROYECTO_ID'', p_values => id, p_clear_cache => ''8'')',
'           WHEN tipo = ''OFERTA''    THEN ',
'               APEX_PAGE.GET_URL(p_page => 15, p_items => ''P15_OFERTA_ID'',    p_values => id, p_clear_cache => ''15'')',
'           ELSE NULL ',
'       END as url_formulario,',
'       -- Nueva columna de control para los atributos HTML del enlace',
'       CASE ',
unistr('           WHEN /*nombre_estados = ''Aprobada para Postulaci\00F3n''*/DEPENDENCIA IS NULL THEN ''style="pointer-events: none; color: #a0a0a0; text-decoration: none; cursor: not-allowed;" title="No permitido para este estado"'''),
'           ELSE ''''',
'       END as link_attributes,',
unistr('       -- Nueva columna opcional por si quieres cambiar el \00EDcono visualmente cuando est\00E9 bloqueado'),
'       CASE ',
unistr('           WHEN /*nombre_estados = ''Aprobada para Postulaci\00F3n''*/DEPENDENCIA IS NULL THEN ''fa-lock'''),
unistr('           ELSE ''fa-search'' -- O el \00EDcono que uses por defecto'),
'       END as link_icon,',
'       nombre_sector,',
'       nombre_tipo_proyecto,',
'       nombre_estados,',
'       CASE nombre_estados ',
unistr('           WHEN ''Aprobada para Postulaci\00F3n''           THEN ''#D4EDDA''  -- Verde claro'),
'           WHEN ''Rechazar Solicitud''                  THEN ''#F8D7DA''  -- Rojo claro',
unistr('           WHEN ''Registrado - Pendiente de Evaluaci\00F3n'' THEN ''#FFF3CD''  -- Amarillo claro'),
'           ELSE ''transparent''',
'       END AS CLASE_ESTADO,',
'       CASE ',
unistr('           WHEN nombre_estados = ''Aprobada para Postulaci\00F3n'' THEN ''Y'''),
'           ELSE ''N''',
'       END as MOSTRAR_BOTON_OFERTA',
'  from LISTADO_GESTION_PRECONTRACTUAL_VIEW'))
,p_ajax_enabled=>'Y'
,p_fixed_header=>'PAGE'
,p_lazy_loading=>false
,p_query_row_template=>2540130677583398057
,p_query_num_rows=>50
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_no_data_found=>'no data found'
,p_query_num_rows_type=>'NEXT_PREVIOUS_LINKS'
,p_query_row_count_max=>500
,p_pagination_display_position=>'BOTTOM_RIGHT'
,p_prn_output=>'N'
,p_prn_format=>'PDF'
,p_sort_null=>'L'
,p_plug_query_strip_html=>'N'
,p_comment=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select ID,',
'       PROYECTO,',
'       MONTO,',
'       FECHA_INICIO,',
'       FECHA_FIN,',
'       PLAZO,',
'       SECTOR_ID,',
'       TIPO_PROYECTO_ID,',
'       OBSERVACIONES,',
'       TIPO,',
'       CASE tipo',
'           WHEN ''SOLICITUD'' THEN ',
'               APEX_PAGE.GET_URL(p_page => 8, p_items => ''P8_SOLICITUD_PROYECTO_ID'', p_values => id, p_clear_cache => ''8'')',
'           WHEN ''OFERTA''    THEN ',
'               APEX_PAGE.GET_URL(p_page => 15, p_items => ''P15_OFERTA_ID'',    p_values => id, p_clear_cache => ''15'')',
'           ELSE NULL ',
'       END as url_formulario,',
'       nombre_sector,',
'       nombre_tipo_proyecto,',
'       nombre_estados,',
'       CASE nombre_estados ',
unistr('       WHEN ''Aprobada para Postulaci\00F3n''           THEN ''#D4EDDA''  -- Verde claro'),
'        WHEN ''Rechazar Solicitud''                  THEN ''#F8D7DA''  -- Rojo claro',
unistr('        WHEN ''Registrado - Pendiente de Evaluaci\00F3n'' THEN ''#FFF3CD''  -- Amarillo claro'),
'        ELSE ''transparent''',
'       END AS CLASE_ESTADO',
'  from LISTADO_GESTION_PRECONTRACTUAL_VIEW/*DESCRIPCION_SOLICITUD,',
'       ESTADOSOLICITUD,',
'       CASE ESTADOSOLICITUD ',
unistr('       WHEN ''Aprobada para Postulaci\00F3n''           THEN ''#D4EDDA''  -- Verde claro'),
'        WHEN ''Rechazar Solicitud''                  THEN ''#F8D7DA''  -- Rojo claro',
unistr('        WHEN ''Registrado - Pendiente de Evaluaci\00F3n'' THEN ''#FFF3CD''  -- Amarillo claro'),
'        ELSE ''transparent''',
'       END AS CLASE_ESTADO,*/',
'       /*ESTADOSOLICITUD1,',
'       JUSTIFICACION_TECNICA,',
'       CIUDAD,',
'       PARROQUIA_ID,',
'       TIPO_PROYECTO_ID,',
'       NOMBRE_TIPO_PROYECTO,',
'       RESPONSABLE_ID,',
'       SECTOR_ID,',
'       SECTOR,',
'       NOMBRE_PARROQUIA,',
'       EMPRESA_ID,',
'       NOMBRE_EMPRESA*/',
'',
'',
'       '))
,p_created_on=>wwv_flow_imp.dz('20260531033509Z')
,p_updated_on=>wwv_flow_imp.dz('20260626031704Z')
,p_created_by=>'GPROY_ELEL'
,p_updated_by=>'GPROY_ELEL'
);
