,p_footer_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<div id="calendar-context-menu" style="display:none; position:fixed; z-index:999999; background:#ffffff; border:1px solid #cbd5e1; box-shadow: 0 10px 15px -3px rgba(0,0,0,0.1), 0 4px 6px -2px rgba(0,0,0,0.05); padding: 6px 0; min-width: 220px; border'
||'-radius: 8px;">',
'    <ul style="list-style:none; padding:0; margin:0;">',
'        <li id="opt-anexo-volumen" style="padding: 10px 16px; cursor: pointer; font-family: -apple-system, BlinkMacSystemFont, ''Segoe UI'', Roboto, Helvetica, Arial, sans-serif; font-size: 14px; color: #1e293b; display: flex; align-items: center; font'
||'-weight: 500; transition: background 0.2s;">',
'            <span class="fa fa-file-text-o" style="margin-right: 12px; color: #0284c7; font-size: 16px;"></span>',
'            Anexo de Volumen de Obra',
'        </li>',
'    </ul>',
'</div>',
'',
'<style>',
'#calendar-context-menu li:hover {',
'    background-color: #f1f5f9 !important;',
'    color: #0284c7 !important;',
'}',
'</style>'))
,p_autocomplete_on_off=>'OFF'
,p_javascript_code_onload=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('// Cerrar el men\00FA si hacen clic izquierdo en cualquier otro lugar de la pantalla'),
'$(document).on("mousedown", function(e) {',
'    if (!$(e.target).closest("#calendar-context-menu").length) {',
'        $("#calendar-context-menu").hide();',
'    }',
'});',
'',
unistr('// Acci\00F3n de clic sobre "Anexo de Volumen de Obra" - APERTURA MODAL DEFINITIVA'),
'$(document).on("click", "#opt-anexo-volumen", function() {',
'    $("#calendar-context-menu").hide();',
'    ',
'    var fechaParametro = window.apexSelectedCalendarDateLatina || '''';',
'    ',
'    // Llamamos al proceso PL/SQL del servidor',
'    apex.server.process(',
'        ''OBTENER_URL_MODAL'', ',
'        {',
'            x01: fechaParametro ',
'        },',
'        {',
'            dataType: ''text'',',
'            loadingIndicator: ''#calendar-context-menu'',',
'            success: function(pData) {',
'                var urlSegura = pData.trim();',
'                ',
'                if (urlSegura) {',
unistr('                    // Usamos la API de navegaci\00F3n nativa para abrir el di\00E1logo pasando la URL que ya viene con su Checksum seguro'),
'                    apex.navigation.dialog(',
'                        urlSegura,',
'                        { ',
'                            title: ''Anexo Volumen de Obra'', ',
'                            height: ''auto'', ',
'                            width: ''720'', ',
'                            modal: true ',
'                        },',
'                        ''a-Dialog--standard'',',
'                        $(''#calendar-context-menu'')',
'                    );',
'                } else {',
unistr('                    console.error("El servidor retorn\00F3 una URL vac\00EDa.");'),
'                }',
'            },',
'            error: function(xhr, status, error) {',
'                console.error("Error al obtener la URL encriptada:", error);',
'            }',
'        }',
'    );',
'});'))
,p_inline_css=>wwv_flow_string.join(wwv_flow_t_varchar2(
'#calendar-context-menu li:hover {',
