wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(37516798482344802)
,p_plug_name=>'Cronograma de Actividades'
,p_static_id=>'cronograma-de-actividades'
,p_parent_plug_id=>wwv_flow_imp.id(18784032111042336)
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_escape_on_http_output=>'Y'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>10
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
'    lar.actividad_id                      AS id_evento,',
'    cad.descripcion                       AS titulo_actividad,',
'    lar.actividad_realizada               AS detalle_realizado,',
unistr('    -- Determinamos la fecha/hora de inicio. Si HORA_INICIO est\00E1 vac\00EDa, usamos la FECHA_INICIO del cronograma'),
'    COALESCE(cad.hora_inicio, CAST(ca.fecha_inicio AS TIMESTAMP)) AS fecha_hora_inicio,',
unistr('    -- Determinamos la fecha/hora de fin. Si HORA_FIN est\00E1 vac\00EDa, usamos la FECHA_FIN del cronograma'),
'    COALESCE(cad.hora_fin, CAST(ca.fecha_fin AS TIMESTAMP))    AS fecha_hora_fin,',
'    -- Clase CSS opcional por si quieres aplicar colores a los bloques de actividades',
'    --''actividad-cronograma-style''          AS clase_css,',
unistr('    -- Evaluaci\00F3n de bloqueo seg\00FAn existencia de Registro de Volumen de Obra'),
'    CASE ',
'        WHEN vo.LIBRO_OBRA_ACTIVIDADES_REALIZADAS_ACTIVIDAD_ID IS NOT NULL THEN ''evento-bloqueado''',
'        ELSE ''evento-disponible''',
'    END AS clase_css,',
'    CASE ',
'        WHEN vo.LIBRO_OBRA_ACTIVIDADES_REALIZADAS_ACTIVIDAD_ID IS NOT NULL THEN ''SI''',
'        ELSE ''NO''',
'    END AS es_bloqueado',
'',
'FROM libro_obra_actividades_realizadas lar',
'INNER JOIN cronogra_actividades_detalles cad ',
'    ON lar.actividad_id_cronograma = cad.actividad_id',
'INNER JOIN cronograma_actividades ca ',
'    ON cad.cronograma_id = ca.cronograma_id',
'LEFT JOIN anexo_volumen_de_obra vo ',
'    ON vo.LIBRO_OBRA_ACTIVIDADES_REALIZADAS_ACTIVIDAD_ID = lar.actividad_id',
'',
unistr('WHERE ca.proyecto_id = :P14_PROYECTO_ID -- Reemplaza por tu \00EDtem real de Proyecto')))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_CSS_CALENDAR'
,p_ajax_items_to_submit=>'P14_PROYECTO_ID'
,p_plugin_init_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'function(options) {',
'    // Escuchamos el clic derecho directamente sobre los elementos que tienen fecha en el calendario',
'    $(document).on("contextmenu", ".fc-daygrid-day, .fc-timegrid-slot, [data-date]", function(e) {',
'        ',
unistr('        // Localizamos el contenedor de fecha m\00E1s cercano'),
'        var cell = $(this).closest(''[data-date]'');',
'        ',
'        if (cell.length > 0) {',
'            var dateStr = cell.attr(''data-date''); // Formato ''YYYY-MM-DD''',
'            ',
'            // Calculamos el Hoy real de Ecuador',
'            var hoy = new Date();',
'            var yyyy = hoy.getFullYear();',
'            var mm = String(hoy.getMonth() + 1).padStart(2, ''0'');',
'            var dd = String(hoy.getDate()).padStart(2, ''0'');',
'            var hoyEcStr = yyyy + ''-'' + mm + ''-'' + dd;',
'',
unistr('            // Si es menor que hoy (el pasado), no hacemos nada y dejamos el men\00FA de Chrome/Edge normal'),
'            if (dateStr < hoyEcStr) {',
'                $("#calendar-context-menu").hide();',
'                return true; ',
'            }',
'            ',
'            // --- SI ES HOY O FUTURO ---',
unistr('            e.preventDefault(); // Cancelamos el men\00FA nativo del navegador para usar el nuestro'),
'            ',
unistr('            // Convertimos a formato latino para pasarlo a la P\00E1gina 30'),
'            var parts = dateStr.split(''-'');',
'            window.apexSelectedCalendarDateLatina = parts[2] + ''/'' + parts[1] + ''/'' + parts[0];',
'            ',
unistr('            // Forzamos la aparici\00F3n del men\00FA en la capa m\00E1s alta de la pantalla usando CSS directo'),
'            $("#calendar-context-menu").css({',
'                "top": e.clientY + "px",',
'                "left": e.clientX + "px",',
'                "display": "block"',
'            });',
'        }',
'    });',
'',
'    return options;',
'}'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'calendar_views_and_navigation', 'month:week:day:list:navigation',
  'css_class', 'CLASE_CSS',
  'display_column', 'TITULO_ACTIVIDAD',
  'drag_and_drop', 'N',
  'end_date_column', 'FECHA_HORA_FIN',
  'event_sorting', 'AUTOMATIC',
