  'view_edit_link', 'f?p=&APP_ID.:21:&SESSION.::&DEBUG.::P21_FECHA_INICIO,P21_FECHA_FIN,P21_LIBRO_OBRA_ACTIVIDADES_REALIZADAS_ACTIVIDAD_ID:&FECHA_HORA_INICIO.,&FECHA_HORA_FIN.,&ID_EVENTO.')).to_clob
