wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(18784837777042344)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Fetch Contrato'
,p_static_id=>'fetch-contrato'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN ',
' --:P14_PROYECTO_ID:=1;',
' select PROYECTO_CONTRATO_VIEW.NOMBRE_PROYECTO,',
'    PROYECTO_CONTRATO_VIEW.MONTO as MONTO,',
'    PROYECTO_CONTRATO_VIEW.FECHA_CONTRATO as FECHA_CONTRATO,',
'    PROYECTO_CONTRATO_VIEW.FECHA_FIN as FECHA_FIN,',
'    PROYECTO_CONTRATO_VIEW.TIEMPO_MESES as TIEMPO_MESES,',
'    PROYECTO_CONTRATO_VIEW.ANTICIPO_VALOR as ANTICIPO_VALOR,',
'    PROYECTO_CONTRATO_VIEW.NOMBRE_TIPO_PROYECTO as NOMBRE_TIPO_PROYECTO,',
'    PROYECTO_CONTRATO_VIEW.CONTRATO_ID as CONTRATO_ID   ',
'   into :P14_NOMBRE_PROYECTO,',
'        :P14_MONTO,',
'        :P14_FECHA_CONTRATO,',
'        :P14_FECHA_FIN,',
'        :P14_TIEMPO_MESES,',
'        :P14_ANTICIPO_VALOR,',
'        :P14_NOMBRE_TIPO_PROYECTO,',
'        :P14_CONTRATO_ID',
' from PROYECTO_CONTRATO_VIEW PROYECTO_CONTRATO_VIEW',
' WHERE PROYECTO_ID=:P14_PROYECTO_ID;',
'',
' /*Recuperar el lId del Libro de Obra,*/',
' SELECT libro_obra_id',
'   INTO :P14_LIBRO_OBRA_ID',
'  FROM LIBRO_DE_OBRA',
' WHERE CONTRATO_ID=:P14_CONTRATO_ID;',
' EXCEPTION ',
'   WHEN NO_dATA_FOUND then',
'      raise_application_error(-20100,''Contrsto no encontrado.'');',
' END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>18784837777042344
,p_created_on=>wwv_flow_imp.dz('20260627032410Z')
,p_updated_on=>wwv_flow_imp.dz('20260718182927Z')
,p_created_by=>'GPROY_ELEL'
,p_updated_by=>'GPROY_ELEL'
);
