 p_id=>wwv_flow_imp.id(18616467199979877)
,p_plug_name=>'Cronograma de Actividades'
,p_static_id=>'cronograma-de-actividades'
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_escape_on_http_output=>'Y'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>10
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT act.actividad_id,',
'       act.cronograma_id,',
unistr('       -- El t\00EDtulo que ver\00E1 el usuario en el calendario (puedes concatenar el contrato si deseas)'),
'       act.descripcion AS titulo_actividad,',
unistr('       -- Combinamos el d\00EDa del maestro con las horas del detalle para que el calendario entienda la l\00EDnea de tiempo'),
'       CAST(cro.fecha_inicio AS TIMESTAMP) + (act.hora_inicio - TRUNC(act.hora_inicio)) AS fecha_hora_inicio,',
'       CAST(cro.fecha_inicio AS TIMESTAMP) + (act.hora_fin - TRUNC(act.hora_fin)) AS fecha_hora_fin',
'  FROM gproy_elel.CRONOGRA_ACTIVIDADES_DETALLES act',
'  JOIN gproy_elel.cronograma_actividades cro ON act.cronograma_id = cro.cronograma_id',
'WHERE cro.oferta_id=:P16_PROYECTO_ID;'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_CSS_CALENDAR'
,p_ajax_items_to_submit=>'P16_PROYECTO_ID'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'calendar_views_and_navigation', 'month:week:day:list:navigation',
  'create_link', 'f?p=&APP_ID.:17:&SESSION.::&DEBUG.::P17_CRONOGRAMA_ID,P17_FECHA_FIN,P17_FECHA_INICIO,P17_PROYECTO_ID:,&APEX$NEW_END_DATE.,&APEX$NEW_START_DATE.,&P16_PROYECTO_ID.',
  'display_column', 'TITULO_ACTIVIDAD',
  'drag_and_drop', 'Y',
  'drag_and_drop_plsql_code', wwv_flow_string.join(wwv_flow_t_varchar2(
    'BEGIN',
    '    -- Validamos si la nueva fecha de inicio es menor a hoy',
    '    IF :APEX$NEW_START_DATE < TRUNC(SYSDATE) THEN',
    '        -- Levantamos un error nativo de Oracle. ',
    unistr('        -- APEX lo capturar\00E1, mostrar\00E1 el mensaje en pantalla y revertir\00E1 el evento visualmente.'),
    unistr('        RAISE_APPLICATION_ERROR(-20001, ''No es posible mover o programar cronogramas a d\00EDas pasados.'');'),
    '    ELSE',
    unistr('        -- Si la fecha es v\00E1lida, actualizamos la tabla maestro de forma directa y ultra r\00E1pida'),
    '        UPDATE gproy_elel.cronograma_actividades',
    '           SET fecha_inicio = CAST(:APEX$NEW_START_DATE AS DATE),',
    '               fecha_fin    = CAST(:APEX$NEW_END_DATE AS DATE)',
    '         WHERE cronograma_id = :APEX$PK_VALUE; ',
    unistr('         -- :APEX$PK_VALUE contiene autom\00E1ticamente el ID del registro movido'),
    '    END IF;',
    'END;')),
  'end_date_column', 'FECHA_HORA_FIN',
  'event_sorting', 'AUTOMATIC',
  'first_hour', '9',
  'maximum_events_day', '10',
  'multiple_line_event', 'Y',
  'primary_key_column', 'CRONOGRAMA_ID',
  'responsive_list_view', 'Y',
  'show_time', 'Y',
  'show_tooltip', 'Y',
  'show_weekend', 'Y',
  'start_date_column', 'FECHA_HORA_INICIO',
  'time_format', '00',
  'view_edit_link', 'f?p=&APP_ID.:17:&SESSION.::&DEBUG.::P17_CRONOGRAMA_ID,P17_FECHA_INICIO,P17_FECHA_FIN:&CRONOGRAMA_ID.,&FECHA_FIN.,&FECHA_INICIO.')).to_clob
,p_created_on=>wwv_flow_imp.dz('20260622032332Z')
,p_updated_on=>wwv_flow_imp.dz('20260630151424Z')
,p_created_by=>'GPROY_ELEL'
,p_updated_by=>'GPROY_ELEL'
);
