,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>10
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_read_only_when_type=>'FUNCTION_BODY'
,p_plug_read_only_when=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_fecha    DATE;',
'    v_string   VARCHAR2(100) := :P17_FECHA_INICIO;',
'    v_hoy_ec   DATE;',
'BEGIN',
unistr('    -- 1. Si est\00E1 vac\00EDo, no se bloquea'),
'    IF v_string IS NULL THEN',
'        RETURN FALSE;',
'    END IF;',
'',
'    -- 2. Forzamos el recorte a los primeros 10 caracteres para limpiar la hora',
'    v_string := SUBSTR(TRIM(v_string), 1, 10);',
'',
unistr('    -- 3. Conversi\00F3n segura de la fecha elegida en el calendario'),
'    BEGIN',
'        IF INSTR(v_string, ''/'') > 0 THEN',
'            v_fecha := TO_DATE(v_string, ''DD/MM/YYYY'');',
'        ELSIF INSTR(v_string, ''-'') > 0 THEN',
'            v_fecha := TO_DATE(v_string, ''YYYY-MM-DD'');',
'        ELSE',
'            v_fecha := TO_DATE(v_string);',
'        END IF;',
'    EXCEPTION',
'        WHEN OTHERS THEN',
'            v_fecha := NULL;',
'    END;',
'',
unistr('    -- 4. SINCRONIZACI\00D3N CON ECUADOR:'),
unistr('    -- Como tu servidor ya vive en el d\00EDa de ma\00F1ana (27/06), le restamos 1 d\00EDa '),
'    -- para forzarlo a evaluar con base al "hoy" real de Ecuador (26/06).',
'    v_hoy_ec := TRUNC(SYSDATE) - 1;',
'',
unistr('    -- 5. Evaluaci\00F3n definitiva:'),
'    IF v_fecha IS NOT NULL THEN',
'        -- Si la fecha elegida coincide con el hoy de Ecuador, se permite editar',
'        IF TRUNC(v_fecha) = v_hoy_ec THEN',
'            RETURN FALSE; ',
unistr('        -- Si es menor al hoy de Ecuador, entonces s\00ED es el pasado y se bloquea'),
'        ELSIF TRUNC(v_fecha) < v_hoy_ec THEN',
'            RETURN TRUE;',
'        ELSE',
'            RETURN FALSE; -- Es el futuro en Ecuador',
'        END IF;',
'    END IF;',
'',
'    RETURN FALSE;',
'END;'))
,p_plug_read_only_when2=>'PLSQL'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
,p_created_on=>wwv_flow_imp.dz('20260622033017Z')
,p_updated_on=>wwv_flow_imp.dz('20260627004857Z')
,p_created_by=>'GPROY_ELEL'
,p_updated_by=>'GPROY_ELEL'
);
