'    v_hoy_ec := TRUNC(SYSDATE) - 1;',
'',
unistr('    -- 5. Evaluaci\00F3n definitiva:'),
'    IF v_fecha IS NOT NULL THEN',
'        -- Si la fecha elegida coincide con el hoy de Ecuador, se permite editar',
'        IF TRUNC(v_fecha) = v_hoy_ec THEN',
'            RETURN FALSE; ',
unistr('        -- Si es menor al hoy de Ecuador, entonces s\00ED es el pasado y se bloquea'),
'        ELSIF TRUNC(v_fecha) < v_hoy_ec THEN',
'            RETURN TRUE;',
'        ELSE',
'            RETURN FALSE; -- Es el futuro en Ecuador',
'        END IF;',
'    END IF;',
'',
'    RETURN FALSE;',
'END;'))
,p_created_on=>wwv_flow_imp.dz('20260622034713Z')
,p_updated_on=>wwv_flow_imp.dz('20260630233827Z')
,p_created_by=>'GPROY_ELEL'
,p_updated_by=>'GPROY_ELEL'
);
