wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(18893804496236816)
,p_event_id=>wwv_flow_imp.id(18893757156236815)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_name=>'Sumatoria Total'
,p_static_id=>'sumatoria-total'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'js_code', wwv_flow_string.join(wwv_flow_t_varchar2(
    unistr('// Esperar a que la regi\00F3n del Interactive Grid est\00E9 completamente inicializada'),
    'apex.region("mi_ig_volumen").createMenu(); // Asegura la carga del widget',
    '',
    'var gridRegion = apex.region("mi_ig_volumen");',
    '',
    'if (gridRegion) {',
    '    // Escuchar el evento cuando el modelo de la IG se crea o se actualiza',
    '    gridRegion.widget().on("interactivegridviewmodelcreate", function(event, ui) {',
    '        var model = ui.model;',
    '        ',
    unistr('        // Cada vez que ocurra una notificaci\00F3n de cambio (notified) en los datos...'),
    '        model.subscribe({',
    '            onChange: function(type, change) {',
    '                // Si el cambio fue actualizar una celda, agregar o borrar una fila',
    '                if (type === "set" || type === "addData" || type === "metaChange") {',
    '                    ',
    '                    var sumaTotal = 0;',
    '                    ',
    unistr('                    // Recorremos de forma ultra r\00E1pida el modelo consolidado en memoria'),
    '                    model.forEach(function(record) {',
    '                        var meta = model.getRecordMetadata(model.getRecordId(record));',
    '                        // Saltamos las filas que el usuario haya eliminado en pantalla',
    '                        if (!meta.deleted) {',
    '                            var valorFila = parseFloat(model.getValue(record, "TOTAL"));',
    '                            if (!isNaN(valorFila)) {',
    '                                sumaTotal += valorFila;',
    '                            }',
    '                        }',
    '                    });',
    '                    ',
    '                    // Asignamos el valor exacto en tiempo real al elemento maestro',
    '                    apex.item("P21_TOTAL").setValue(sumaTotal.toFixed(2));',
    '                }',
    '            }',
    '        });',
    '    });',
    '}')))).to_clob
,p_created_on=>wwv_flow_imp.dz('20260627233229Z')
,p_updated_on=>wwv_flow_imp.dz('20260627235426Z')
,p_created_by=>'GPROY_ELEL'
,p_updated_by=>'GPROY_ELEL'
);
