wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(18894278704236820)
,p_event_id=>wwv_flow_imp.id(18894116247236819)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_name=>'Suma Total'
,p_static_id=>'suma-total'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'js_code', wwv_flow_string.join(wwv_flow_t_varchar2(
    'console.log("1. Inicializando script de sumatoria...");',
    '',
    'function inicializarSumatoriaIG() {',
    '    var region = apex.region("mi_ig_volumen");',
    '    ',
    '    if (!region) {',
    unistr('        console.log("Error: No se encontr\00F3 la regi\00F3n con Static ID ''mi_ig_volumen''");'),
    '        return;',
    '    }',
    '',
    '    var widget = region.widget();',
    '    if (!widget) {',
    unistr('        console.log("El widget a\00FAn no est\00E1 listo, reintentando en 50ms...");'),
    '        setTimeout(inicializarSumatoriaIG, 50);',
    '        return;',
    '    }',
    '',
    '    var gridView = widget.interactiveGrid("getViews", "grid");',
    '    var model = gridView ? gridView.model : null;',
    '',
    '    if (!model) {',
    unistr('        console.log("El modelo de datos de la Grid a\00FAn no existe, reintentando en 50ms...");'),
    '        setTimeout(inicializarSumatoriaIG, 50);',
    '        return;',
    '    }',
    '',
    unistr('    console.log("2. \00A1Modelo de la IG detectado con \00E9xito!");'),
    '',
    unistr('    // Funci\00F3n principal de c\00E1lculo'),
    unistr('    // Funci\00F3n principal de c\00E1lculo optimizada para decimales y formatos regionales'),
    '    var calcularGranTotal = function() {',
    unistr('        console.log("3. Ejecutando la funci\00F3n calcularGranTotal() con soporte decimal...");'),
    '        var sumaTotal = 0;',
    '        ',
    '        model.forEach(function(record) {',
    '            var meta = model.getRecordMetadata(model.getRecordId(record));',
    '            if (!meta || !meta.deleted) {',
    '                // 1. Obtenemos el valor crudo en texto',
    '                var valorCelda = model.getValue(record, "TOTAL");',
    '                var valorFila = 0;',
    '',
    '                if (valorCelda !== null && valorCelda !== undefined && valorCelda !== "") {',
    unistr('                    // 2. Usamos el API nativo de APEX para convertir a n\00FAmero respetando comas/puntos decimales'),
    '                    valorFila = apex.locale.toNumber(valorCelda);',
    '                }',
    '                ',
    unistr('                // Si es un n\00FAmero v\00E1lido de JavaScript, lo acumulamos'),
    '                if (!isNaN(valorFila)) {',
    '                    sumaTotal += valorFila;',
    '                }',
    '            }',
    '        });',
    '        ',
    '        console.log("4. Suma decimal calculada exitosamente en JS:", sumaTotal);',
    '        ',
    unistr('        // 3. Asignamos el valor al \00EDtem formate\00E1ndolo con la configuraci\00F3n regional de la app'),
    '        // Esto asegura que si tu app usa coma para decimales, se muestre con coma en P21_TOTAL',
    '        apex.item("P21_TOTAL").setValue(apex.locale.formatNumber(sumaTotal, "999G999G999G990D00"));',
    '    };',
    '',
    unistr('    // Ejecuci\00F3n inicial inmediata ya que el modelo existe'),
    '    calcularGranTotal();',
    '',
    unistr('    // Suscripci\00F3n a cambios futuros (ediciones, insertar filas, borrar filas)'),
    '    model.subscribe({',
    '        onChange: function(type, change) {',
    '            console.log("-> Cambio detectado en el modelo. Tipo de evento:", type);',
    '            if (type === "set" || type === "addData" || type === "metaChange") {',
    '                calcularGranTotal();',
    '            }',
    '        }',
    '    });',
    '}',
    '',
    unistr('// Lanzamos la funci\00F3n inmediatamente en el Page Load'),
    'inicializarSumatoriaIG();')))).to_clob
,p_created_on=>wwv_flow_imp.dz('20260628024255Z')
,p_updated_on=>wwv_flow_imp.dz('20260628030945Z')
,p_created_by=>'GPROY_ELEL'
