 p_id=>wwv_flow_imp.id(38612500405551768)
,p_plug_name=>'Lista de Notificaciones '
,p_static_id=>'lista-de-notificaciones'
,p_region_name=>'panel_notificaciones'
,p_region_template_options=>'#DEFAULT#:t-CardsRegion--hideHeader js-addHiddenHeadingRoleDesc:t-Form--stretchInputs'
,p_plug_template=>2074200852440250129
,p_plug_display_sequence=>10
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
'    notifica_id AS id,',
'    mensaje     AS title,',
'    -- Formato de tiempo amigable (Ej: Hace 2 min)',
'    apex_util.get_since(fecha_registro) AS subtitle, ',
'    CASE ATENDIDO_SN WHEN ''N'' THEN ''u-color-1'' ELSE ''u-color-gray'' END AS card_color,',
unistr('    -- Enlace de redirecci\00F3n seg\00FAn el tipo de notificaci\00F3n'),
'    CASE ',
'        WHEN proyecto_id IS NOT NULL THEN ',
'            apex_page.get_url(p_page => 10, p_items => ''P10_PROYECTO_ID'', p_values => proyecto_id)',
'        WHEN oferta_id IS NOT NULL THEN ',
'            apex_page.get_url(p_page => 11, p_items => ''P11_OFERTA_ID'', p_values => oferta_id)',
'        ELSE ''#''',
'    END AS link_url',
'FROM notificaciones',
unistr('--WHERE destino_usuari = :APP_USER_ID -- O la l\00F3gica que uses para tu ID de usuario'),
'ORDER BY fecha_registro DESC',
'FETCH FIRST 50 ROWS ONLY;'))
