,p_display_sequence=>20
,p_region_css_classes=>'search-results'
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'t-MediaList--showDesc:t-MediaList--stack'
,p_display_point=>'REGION_POSITION_02'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select "ID_PAIS",',
'    null LINK_CLASS,',
'    apex_page.get_url(p_items => ''P38_ID_PAIS'', p_values => "ID_PAIS") LINK,',
'    null ICON_CLASS,',
'    null LINK_ATTR,',
'    null ICON_COLOR_CLASS,',
'    case when coalesce(:P38_ID_PAIS,''0'') = "ID_PAIS"',
'      then ''is-active'' ',
'      else '' ''',
'    end LIST_CLASS,',
'    (substr("NOMBRE_PAIS", 1, 50)||( case when length("NOMBRE_PAIS") > 50 then ''...'' else '''' end )) LIST_TITLE,',
'    (substr("CODIGO_ISO", 1, 50)||( case when length("CODIGO_ISO") > 50 then ''...'' else '''' end )) LIST_TEXT,',
'    null LIST_BADGE',
'from "PAIS" x',
'where (:P38_SEARCH is null',
